(7514476, 1199909, 30861, '<td valign="top">You know what might have been wonderful? If you''d made the top half of the montage first then destroyed the crease line and the pure symmetry of the clouds before adding the flipped, bottom panel :-) But it''s a lovely image regardless, and very nicely rendered.</td>', 'You know what might have been wonderful? If you''d made the top half of the montage first then destroyed the crease line and the pure symmetry of the clouds before adding the flipped, bottom panel :-) But it''s a lovely image regardless, and very nicely rendered.', '2017-05-18 17:52:00.000000', NULL, 1),
(7514477, 1199896, 30861, '<td valign="top">LOL</td>', 'LOL', '2017-05-18 17:52:16.000000', NULL, 1),
(7514648, 1199909, 182284, '<td valign="top">This is one of my favorites. I love your processing and would not change in any way. Clearly this will make ribbon. 10</td>', 'This is one of my favorites. I love your processing and would not change in any way. Clearly this will make ribbon. 10', '2017-05-19 09:32:49.000000', NULL, 1),
(7514650, 1199932, 182284, '<td valign="top">This is another favorite of mine. I love it when there is nothing else I would do to change this photo. Love your process and subjects. 10</td>', 'This is another favorite of mine. I love it when there is nothing else I would do to change this photo. Love your process and subjects. 10', '2017-05-19 09:34:30.000000', NULL, 1),
(7514651, 1198714, 182284, '<td valign="top">I love the layering, this is a beautiful work of art. I love this technique and the color in the center makes it pop. 10</td>', 'I love the layering, this is a beautiful work of art. I love this technique and the color in the center makes it pop. 10', '2017-05-19 09:36:13.000000', NULL, 1),
(7514653, 1199496, 182284, '<td valign="top">Very nice work of art. I love the center piece and the object just below gives us a feeling of meditation. If I created this the only thing I would do is try to match the lower color just a little closer to the cool blue in the top, other than that this is a beautiful piece. 9</td>', 'Very nice work of art. I love the center piece and the object just below gives us a feeling of meditation. If I created this the only thing I would do is try to match the lower color just a little closer to the cool blue in the top, other than that this is a beautiful piece. 9', '2017-05-19 09:42:17.000000', NULL, 1),
(7514654, 1199732, 182284, '<td valign="top">This is a great shot. This one made me smile. 9</td>', 'This is a great shot. This one made me smile. 9', '2017-05-19 09:43:07.000000', NULL, 1),
(7514655, 1199945, 182284, '<td valign="top">This is beautiful, you must tell us how this was created. Very nice work of Art. 9</td>', 'This is beautiful, you must tell us how this was created. Very nice work of Art. 9', '2017-05-19 09:45:08.000000', NULL, 1),
