(7514666, 1199992, 182284, '<td valign="top">Very nice combination of very different photos. They compliment each other, Very well done. 8</td>', 'Very nice combination of very different photos. They compliment each other, Very well done. 8', '2017-05-19 09:56:06.000000', NULL, 1),
